// Welcher Fokus gilt, steht im Speicher des Browsers - unter demselben
// Schluessel wie der uebrige Zustand. Hier gelesen und nicht in der App
// gewaehlt, damit PLAN, TARGET und REST ueberall dasselbe meinen. Ein
// Wechsel laedt die Seite neu; der Plan steckt in Hunderten von Zeilen,
// und ein Tausch mitten im Betrieb hiesse, dass die halbe App noch mit
// dem alten rechnet.
const AKTIV = (() => {
  try {
    const key = JSON.parse(localStorage.getItem('workout.state.v1') || '{}').focus;
    if (PLANS[key]) return PLANS[key];
    // Abgeschaffter Fokus: zum benannten Nachfolger, nicht irgendwohin.
    const ersatz = FOKUS_ERSATZ[key];
    return (ersatz && PLANS[ersatz.nach]) || PLANS.standard;
  } catch {
    return PLANS.standard;   // privater Modus: kein Speicher, kein Fokus
  }
})();

export const FOCUS = AKTIV;
// Saetze je Muskelgruppe und Woche, auf die der Plan gerechnet ist.
export const TARGET = AKTIV.target;
// Obergrenze: keine Gruppe kommt darueber, indirekte Anteile eingerechnet.
export const CAP = AKTIV.cap;
// Gruppen ohne eigenes Ziel: ihr Wert faellt aus den uebrigen Gleichungen.
export const DERIVED = AKTIV.derived;
// Erholung: Mindestabstand in Tagen und ab welchem Anteil eine Uebung
// als direkt fuer die Gruppe gilt.
export const REST = AKTIV.rest;
export const PLAN = AKTIV.plan;
